-- Dumping structure for table maxindorental.employees
DROP TABLE IF EXISTS `employees`;
CREATE TABLE IF NOT EXISTS `employees` (
  `EMPLOYEEID` int(11) NOT NULL AUTO_INCREMENT,
  `EMPLOYEECODE` varchar(50) NOT NULL,
  `NAME` varchar(50) DEFAULT NULL,
  `BIRTHDATE` date DEFAULT NULL,
  `BIRTHPLACE` varchar(50) DEFAULT NULL,
  `PHOTO` varchar(50) DEFAULT NULL,
  `UNIT` int(11) DEFAULT NULL,
  `JOBPOSITION` int(11) DEFAULT NULL,
  `ADDRESS` text DEFAULT NULL,
  `DISTRICT` int(11) DEFAULT NULL,
  `CITY` int(11) DEFAULT NULL,
  `PROVINCE` int(11) DEFAULT NULL,
  `EMAIL` varchar(50) DEFAULT NULL,
  `TELP` varchar(50) DEFAULT NULL,
  `IDCARDNUMBER` varchar(50) DEFAULT NULL,
  `MOBILE` varchar(50) DEFAULT NULL,
  `BANKNUMBER` varchar(50) DEFAULT NULL,
  `BANKNAME` varchar(50) DEFAULT NULL,
  `PARENTNAME` varchar(50) DEFAULT NULL,
  `PARENTADDRESS` text DEFAULT NULL,
  `RELATIVENAME` varchar(50) DEFAULT NULL,
  `RELATIVEPHONENUMBER` varchar(50) DEFAULT NULL,
  `RELATION` int(11) DEFAULT NULL,
  `IDCARD` varchar(50) DEFAULT NULL,
  `FAMILYCARD` varchar(50) DEFAULT NULL,
  `ID` int(11) DEFAULT NULL,
  `NPWPSTATUS` int(1) DEFAULT NULL,
  `NPWPFILE` varchar(50) DEFAULT NULL,
  `NPWP` varchar(50) DEFAULT NULL,
  `INSURANCE` int(11) DEFAULT NULL,
  `OTHERINSURANCE` text DEFAULT NULL,
  PRIMARY KEY (`EMPLOYEEID`),
  KEY `JOBPOSITION` (`JOBPOSITION`),
  KEY `UNIT` (`UNIT`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4;

