-- Dumping structure for function maxindorental.imageload
DROP FUNCTION IF EXISTS `imageload`;
DELIMITER //
CREATE FUNCTION `imageload`(
        `imagecol` VARCHAR(50),
        `namecol` VARCHAR(50),
        `uploaddir` VARCHAR(50)
) RETURNS varchar(250) CHARSET utf8mb4
BEGIN
        DECLARE result VARCHAR(250);
        DECLARE class VARCHAR(25);
        SELECT ELT(FLOOR(RAND() * 3 + 1), 'info', 'danger', 'success') INTO class;

        IF( imagecol <> "" ) THEN
                SET result = CONCAT("<img src='",uploaddir,"/",imagecol,"' class='m-image-rounded align-self-end' alt='photo'>");
        ELSE
                SET result = CONCAT("<span class='symbol-label bg-",class," text-white'>",UPPER(LEFT(namecol,1)),"</span>");
        END IF;
        RETURN result;
END//
DELIMITER ;

